#include <assert.h>
#include <pthread.h>
#include <stdio.h>

enum { N = 5 };

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;

int slot = -1;
int has_item = 0;
int consumed_sum = 0;

void* producer(void* arg) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while (has_item) {
            pthread_cond_wait(&not_full, &mutex);
        }
        slot = i;
        has_item = 1;
        printf("produce %d\n", i);
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* consumer(void* arg) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        while (!has_item) {
            pthread_cond_wait(&not_empty, &mutex);
        }
        int value = slot;
        has_item = 0;
        consumed_sum += value;
        printf("consume %d\n", value);
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);

    pthread_t p, c;
    assert(pthread_create(&p, NULL, producer, NULL) == 0);
    assert(pthread_create(&c, NULL, consumer, NULL) == 0);
    assert(pthread_join(p, NULL) == 0);
    assert(pthread_join(c, NULL) == 0);

    assert(consumed_sum == N * (N - 1) / 2);
    puts("all items consumed once");
    return 0;
}
